// RISC (MIPS) 32-bit Fixed Width Encoding

// R-Type Format (Register Operations)
struct R_Type {
    unsigned int Opcode : 6; // Always 0 for R-Type
    unsigned int Rs : 5;     // Source Register 1
    unsigned int Rt : 5;     // Source Register 2
    unsigned int Rd : 5;     // Destination Register
    unsigned int Shamt : 5;  // Shift Amount
    unsigned int Funct : 6;  // Specific Operation Code
};

// I-Type Format (Immediate, Loads, Stores)
struct I_Type {
    unsigned int Opcode : 6; // Defines operation
    unsigned int Rs : 5;     // Base/Source Register
    unsigned int Rt : 5;     // Destination/Target Register
    signed int Immediate : 16; // Sign-extended constant/offset
};

// J-Type Format (Jumps)
struct J_Type {
    unsigned int Opcode : 6;
    unsigned int Address : 26; // Target word address
};
